function header(){return `<div class="ann" id="siteAnnouncement">${esc(DEFAULT_SETTINGS.announcement)}</div><header class="head"><div class="headtop"><a class="logo" href="/"><img id="siteLogo" src="${esc(DEFAULT_SETTINGS.logoUrl)}" alt="Okyanus EDT logo"><span id="siteTitle">${esc(DEFAULT_SETTINGS.siteTitle)}</span></a><form class="search" action="/urunler" method="get" role="search"><input name="q" type="search" placeholder="Ürün, kategori, marka veya paket ara..." aria-label="Ürün ara"><button aria-label="Ara">⌕</button></form><div class="actions"><a href="/">Ana Sayfa</a><a href="/urunler">Ürünler</a><a href="/fotografla-teklif">Fotoğrafla Teklif</a><a href="/iletisim">İletişim</a><a href="/yardim">Site Yardım</a><a href="/uye">Hesabım</a><a class="primary" href="/sepet">Sepet / Teklif</a></div></div><nav class="nav" aria-label="Ana menü"><div class="navin"><a href="/">⌂ Ana Sayfa</a><a href="/urunler">☰ Kategoriler</a><a href="/kampanyalar">Kampanyalar</a><a href="/urunler?filter=discount">İndirimli Ürünler</a><a href="/urunler?filter=new">Yeni Ürünler</a><a href="/markalar">Markalar</a><a href="/urunler?category=deniz-urunleri">Deniz Ürünleri</a><a href="/urunler?category=donuk-urunler">Donuk Ürünler</a><a href="/icerik-studyo">İçerik Stüdyo</a></div></nav></header>`}
