 const script="(function(){var slides=[].slice.call(document.querySelectorAll('[data-slide]')),dots=[].slice.call(document.querySelectorAll('[data-dot]')),i=0,timer;function show(n){i=(n+slides.length)%slides.length;slides.forEach((x,k)=>x.classList.toggle('active',k===i));dots.forEach((x,k)=>x.classList.toggle('active',k===i))}function play(){clearInterval(timer);timer=setInterval(()=>show(i+1),5500)}dots.forEach((d,k)=>d.onclick=()=>{show(k);play()});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)play();const slug=v=>String(v||'').toLocaleLowerCase('tr-TR').normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');const norm=x=>{const txt=[x.category,x.masterCategory,x.subCategory,x.name].join(' ').toLocaleLowerCase('tr-TR');let category=String(x.category||'Diğer Ürünler');if(/deniz|balık|karides|kalamar|ahtapot|su ürün/.test(txt))category='Deniz Ürünleri';else if(/donuk|patates|dondur/.test(txt))category='Donuk Ürünler';else if(/et|kanat|tavuk|piliç|köfte|şarküteri|sucuk|sosis/.test(txt))category='Et & Şarküteri';else if(/süt|peynir|krema|tereyağ|yoğurt/.test(txt))category='Süt & Şarküteri';else if(/yağ/.test(txt))category='Yağlar';else if(/sos|ketçap|mayonez|hardal|sirke/.test(txt))category='Soslar';else if(/baharat|çeşni/.test(txt))category='Baharat';else if(/bakliyat|pirinç|bulgur|makarna|un|şeker|tuz|kuru/.test(txt))category='Kuru Gıda';return {id:String(x.id||slug(x.name)),source_product_id:String(x.id||''),name:String(x.name||'Ürün'),brand:String(x.brand||''),category,package_text:[x.amount,x.package].filter(Boolean).join(' • '),unit:/kg/i.test(String(x.amount||''))?'Kg':'Adet',stock_status:'Fiyat / stok için teklif alın',legacy:true}};const merge=(managed,legacy)=>{const seen=new Set(),out=[];for(const p of managed){const k=String(p.source_product_id||p.id||p.name).toLocaleLowerCase('tr-TR');if(!seen.has(k)){seen.add(k);out.push(p)}}for(const r of legacy){const p=norm(r),k=String(p.source_product_id||p.id||p.name).toLocaleLowerCase('tr-TR');if(!seen.has(k)){seen.add(k);out.push(p)}}return out};const esc=v=>String(v??'').replace(/[&<>\\\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;',\"'\":'&#39;'}[c]));const money=v=>{const n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(n):'Fiyat için teklif alın'};function emoji(p){const c=String(p.category||'').toLocaleLowerCase('tr-TR');return c.includes('deniz')?'🐟':c.includes('donuk')?'❄':c.includes('et')?'🥩':c.includes('süt')?'🧀':c.includes('yağ')?'🫗':c.includes('sos')?'🥫':c.includes('baharat')?'✦':'▣'}function htmlCard(p){const id=String(p.source_product_id||p.id||''),price=p.effectivePrice??p.price??null,img=p.image?'<img loading=\\\"lazy\\\" src=\\\"'+esc(p.image)+'\\\" alt=\\\"'+esc(p.name)+'\\\">':'<div class=\\\"visualFallback\\\"><b>'+emoji(p)+'</b><span>'+esc(p.name)+'</span></div>';return '<article class=\\\"product\\\"><a class=\\\"img\\\" href=\\\"/urun/'+encodeURIComponent(slug(p.name))+'\\\">'+img+'</a><div class=\\\"badges\\\">'+(p.legacy?'<span class=\\\"badge legacyBadge\\\">ESKİ KATALOG</span>':'')+'</div><h3>'+esc(p.name)+'</h3><div class=\\\"meta\\\">'+esc(p.brand||p.category||'Okyanus EDT')+'<br>'+esc(p.package_text||p.unit||'')+'</div><div class=\\\"price\\\"><strong>'+money(price)+'</strong></div><div class=\\\"stock\\\">'+esc(p.stock_status||'Siparişe uygun')+'</div><div class=\\\"qty\\\"><button data-minus>-</button><input type=number min=1 value=1><button data-plus>+</button></div><button class=\\\"add\\\" data-add=\\\"'+esc(id)+'\\\">Sepete / Teklife Ekle</button></article>'}Promise.all([fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]})),fetch('/api/products',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]}))]).then(([j,l])=>{const p=merge(Array.isArray(j.products)?j.products:[],Array.isArray(l.products)?l.products:[]);if(p.length){commerceProducts=document.getElementById('commerce-products');commerceNew=document.getElementById('commerce-new');if(commerceProducts)commerceProducts.innerHTML=p.slice(0,10).map(htmlCard).join('');if(commerceNew)commerceNew.innerHTML=p.slice(10,20).map(htmlCard).join('')}if(Array.isArray(j.categories)&&j.categories.length){const cg=document.getElementById('commerce-categories');if(cg)cg.innerHTML=j.categories.map(c=>'<a class=\\\"cat\\\" href=\\\"/urunler?category='+encodeURIComponent(c.slug||slug(c.name))+'\\\"><span>'+esc(c.icon||'•')+'</span><b>'+esc(c.name||'Kategori')+'</b></a>').join('')}if(Array.isArray(j.campaigns)&&j.campaigns.length){const cp=document.getElementById('commerce-campaign'),c=j.campaigns[0];if(cp)cp.innerHTML='<h3>'+esc(c.title||'Fırsat Ürünleri')+'</h3><p>'+esc(c.description||'')+'</p><a class=\\\"btn\\\" href=\\\"'+esc(c.cta_url||'/kampanyalar')+'\\\">'+esc(c.cta_text||'İncele')+'</a>'}if(Array.isArray(j.sections)&&j.sections.length){const ms=document.getElementById('commerce-managed-sections'),mg=document.getElementById('commerce-managed-sections-grid');if(ms&&mg){mg.innerHTML=j.sections.map(x=>'<article class=\\\"promo\\\"><h3>'+esc(x.title||'Vitrin')+'</h3><p>'+esc(x.source||x.kind||'')+'</p></article>').join('');ms.hidden=false}}}).catch(()=>{});document.addEventListener('click',e=>{const c=e.target.closest('.product');if(!c)return;const q=c.querySelector('input');if(e.target.matches('[data-plus]'))q.value=Math.max(1,Number(q.value||1)+1);if(e.target.matches('[data-minus]'))q.value=Math.max(1,Number(q.value||1)-1);if(e.target.matches('[data-add]')){const id=e.target.getAttribute('data-add'),qty=Math.max(1,Number(q.value||1)),K='oky-commerce-cart-v2';let a=[];try{a=JSON.parse(localStorage.getItem(K)||'[]')}catch{}const name=(c.querySelector('h3')||{}).textContent||'Ürün',ex=a.find(x=>x.id===id);if(ex)ex.qty+=qty;else a.push({id,name,unit:'Adet',qty});localStorage.setItem(K,JSON.stringify(a));e.target.textContent='Sepete Eklendi ✓';setTimeout(()=>e.target.textContent='Sepete / Teklife Ekle',1200)}})})();";
 return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Okyanus EDT | HORECA Gıda Tedariki</title><meta name="description" content="İstanbul HORECA işletmeleri için profesyonel ürün kataloğu, kampanya, teklif ve tedarik."><style>'+css()+'</style></head><body>'+header()+body+footer()+mobile()+'<script>'+script+'</script>'+runtimeSettingsScript()+'</body></html>';
