async function storefront(env){
 let products=[];
 try{
  const DB=env&& (env.DB||env.ADMIN_DB||env["Veritabanı"]||env["Veritabani"]||env["Veritabanı1"]);
  if(DB){
   const has=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='b2b_products_v1'").first();
   if(has){
    const hasMeta=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_product_meta_v1'").first();
    const sql=hasMeta?`SELECT p.id,p.source_product_id,p.name,p.category,p.unit,p.package_text,p.image_url image,p.stock_status,
    (SELECT price FROM b2b_prices_v1 pr WHERE pr.product_id=p.id AND pr.active=1 AND (pr.valid_until IS NULL OR pr.valid_until>datetime('now')) ORDER BY pr.valid_from DESC LIMIT 1) effectivePrice,
    m.description,m.seo_title,m.seo_description,m.featured,m.sort_order,m.brand_id,
    (SELECT name FROM oky_brands_v1 b WHERE b.id=m.brand_id AND b.active=1 LIMIT 1) brand
    FROM b2b_products_v1 p LEFT JOIN oky_product_meta_v1 m ON m.product_id=p.id
    WHERE p.active=1 ORDER BY COALESCE(m.featured,0) DESC,COALESCE(m.sort_order,0),p.updated_at DESC LIMIT 100`
    :`SELECT p.id,p.source_product_id,p.name,p.category,p.unit,p.package_text,p.image_url image,p.stock_status,
    (SELECT price FROM b2b_prices_v1 pr WHERE pr.product_id=p.id AND pr.active=1 AND (pr.valid_until IS NULL OR pr.valid_until>datetime('now')) ORDER BY pr.valid_from DESC LIMIT 1) effectivePrice
    FROM b2b_products_v1 p WHERE p.active=1 ORDER BY p.updated_at DESC LIMIT 100`;
    const rows=(await DB.prepare(sql).all()).results||[];
    products=rows;
   }
  }
 }catch{}
 let banners=[],categories=[],sections=[],campaigns=[],brands=[],delivery=[],helpArticles=[],settings={};
 try{
  const DB=env&& (env.DB||env.ADMIN_DB||env["Veritabanı"]||env["Veritabani"]||env["Veritabanı1"]);
  if(DB){
   const hb=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_banners_v1'").first();
   if(hb)banners=(await DB.prepare("SELECT * FROM oky_storefront_banners_v1 WHERE active=1 AND (start_at IS NULL OR start_at<=datetime('now')) AND (end_at IS NULL OR end_at>=datetime('now')) ORDER BY sort_order,rowid LIMIT 10").all()).results||[];
   const hc=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_categories_v1'").first();
   if(hc)categories=(await DB.prepare("SELECT * FROM oky_storefront_categories_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 30").all()).results||[];
   const hs=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_sections_v1'").first();
   if(hs)sections=(await DB.prepare("SELECT * FROM oky_storefront_sections_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 30").all()).results||[];
   const hcamp=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_campaigns_v1'").first();
   if(hcamp)campaigns=(await DB.prepare("SELECT * FROM oky_campaigns_v1 WHERE active=1 AND (start_at IS NULL OR start_at<=datetime('now')) AND (end_at IS NULL OR end_at>=datetime('now')) ORDER BY priority DESC,sort_order,rowid LIMIT 10").all()).results||[];
   const hbrand=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_brands_v1'").first();
   if(hbrand)brands=(await DB.prepare("SELECT * FROM oky_brands_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 100").all()).results||[];
   const hdel=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_delivery_rules_v1'").first();
   if(hdel)delivery=(await DB.prepare("SELECT * FROM oky_delivery_rules_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 100").all()).results||[];
   const hhelp=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_help_articles_v1'").first();
   if(hhelp)helpArticles=(await DB.prepare("SELECT * FROM oky_help_articles_v1 WHERE active=1 ORDER BY sort_order,rowid LIMIT 100").all()).results||[];
   const hset=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_settings_v1'").first();
   if(hset){const sr=(await DB.prepare("SELECT key,value FROM oky_storefront_settings_v1").all()).results||[];settings=Object.fromEntries(sr.map(x=>[x.key,x.value]));}
  }
 }catch{}
 if(!products.length)products=FALLBACK_PRODUCTS;
 return json({ok:true,build:BUILD,products:products.map(p=>({...p,cardHtml:card(p)})),banners,categories,sections,campaigns,brands,delivery,help:helpArticles,settings:{...DEFAULT_SETTINGS,...settings},legacyCatalogEndpoint:"/api/products"});
}


function runtimeSettingsScript(){return `<script>(function(){function apply(s){s=s||{};var set=(id,key)=>{var e=document.getElementById(id);if(e&&s[key])e.textContent=s[key]};set("siteAnnouncement","announcement");set("siteTitle","siteTitle");set("footerSiteTitle","siteTitle");set("footerText","footerText");set("heroTitle","heroTitle");set("heroSubtitle","heroSubtitle");var logo=document.getElementById("siteLogo");if(logo&&s.logoUrl)logo.src=s.logoUrl;var phone=String(s.phone||"").replace(/[^+0-9]/g,""),wa=String(s.whatsapp||"").replace(/\D/g,""),email=String(s.email||"");["footerPhone","contactPhone"].forEach(id=>{var e=document.getElementById(id);if(e&&s.phone){e.textContent=s.phone;e.href="tel:"+phone}});["footerEmail","contactEmail"].forEach(id=>{var e=document.getElementById(id);if(e&&email){e.href="mailto:"+email;if(id==="footerEmail")e.textContent=email}});["contactWhatsapp","floatWhatsapp"].forEach(id=>{var e=document.getElementById(id);if(e&&wa)e.href="https://api.whatsapp.com/send?phone="+wa})}fetch("/api/storefront-v2",{headers:{accept:"application/json"},cache:"no-store"}).then(r=>r.json()).then(j=>apply(j.settings)).catch(()=>{})})();</script>`}
function commerceClientShell(title,body,script){
 return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>'+esc(title)+'</title><style>'+css()+'.catalogTools{display:grid;grid-template-columns:1fr auto;gap:8px;margin:0 0 14px}.catalogTools input,.catalogTools select{padding:11px;border:1px solid #bfd3e1;border-radius:10px}.commerceGrid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.commerceBox{background:#fff;border:1px solid var(--line);border-radius:16px;padding:16px}.commerceCartRow{display:grid;grid-template-columns:1fr 90px 80px 38px;gap:8px;align-items:center;padding:10px;border:1px solid var(--line);border-radius:12px;margin:7px 0}@media(max-width:1000px){.commerceGrid{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.commerceGrid{grid-template-columns:repeat(2,1fr);gap:8px}.catalogTools{grid-template-columns:1fr}.commerceCartRow{grid-template-columns:minmax(0,1fr) 68px 44px}.commerceCartRow .u{display:none}.commerceCartRow input{min-width:0;width:100%}.commerceCartRow button{min-width:44px;min-height:44px}.page .form input,.page .form textarea,.page .form select{min-width:0}}</style></head><body>'+header()+body+footer()+mobile()+(script?'<script>'+script+'</script>':'')+'</body></html>';
}
function commerceCatalogPage(){
 const body='<main class="wrap"><section class="section"><div class="sectionhead"><div><h2>Tüm Ürünler</h2><p>Okyanus EDT profesyonel HORECA kataloğu. Satış fiyatı yönetim panelinde girilmiş ürünlerde doğrudan görünür.</p></div><a href="/kampanyalar">Kampanyalar →</a></div><form class="catalogTools" id="catalogTools"><input id="cq" placeholder="Ürün, kategori veya marka ara"><select id="cc"><option value="">Tüm kategoriler</option></select></form><div id="catalogCount" class="meta"></div><div id="catalogGrid" class="commerceGrid"></div></section>'+contactStrip()+'</main>';
 const script="(function(){const K='oky-commerce-cart-v2';const read=()=>{try{return JSON.parse(localStorage.getItem(K)||'[]')}catch{return[]}},write=a=>localStorage.setItem(K,JSON.stringify(a));const slug=v=>String(v||'').toLocaleLowerCase('tr-TR').normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');const esc=v=>String(v??'').replace(/[&<>\\\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;',\"'\":'&#39;'}[c]));const money=v=>{const n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(n):'Fiyat için teklif alın'};const emoji=p=>{const c=String(p.category||'').toLocaleLowerCase('tr-TR');return c.includes('deniz')?'🐟':c.includes('donuk')||c.includes('patates')?'❄':c.includes('et')||c.includes('kanat')?'🥩':c.includes('süt')||c.includes('peynir')?'🧀':c.includes('yağ')?'🫗':c.includes('sos')?'🥫':c.includes('baharat')?'✦':c.includes('bakliyat')||c.includes('kuru')?'🌾':'▣'};const normalizeLegacy=x=>{const txt=[x.category,x.masterCategory,x.subCategory,x.name].join(' ').toLocaleLowerCase('tr-TR');let category=String(x.category||'Diğer Ürünler');if(/deniz|balık|karides|kalamar|ahtapot|su ürün/.test(txt))category='Deniz Ürünleri';else if(/donuk|patates|dondur/.test(txt))category='Donuk Ürünler';else if(/et|kanat|tavuk|piliç|köfte|şarküteri|sucuk|sosis/.test(txt))category='Et & Şarküteri';else if(/süt|peynir|krema|tereyağ|yoğurt/.test(txt))category='Süt & Şarküteri';else if(/yağ/.test(txt))category='Yağlar';else if(/sos|ketçap|mayonez|hardal|sirke/.test(txt))category='Soslar';else if(/baharat|çeşni/.test(txt))category='Baharat';else if(/bakliyat|pirinç|bulgur|makarna|un|şeker|tuz|kuru/.test(txt))category='Kuru Gıda';const pack=[x.amount,x.package].filter(Boolean).join(' • ');return {id:String(x.id||slug(x.name)),source_product_id:String(x.id||''),name:String(x.name||'Ürün'),brand:String(x.brand||''),category,package_text:pack,unit:/kg/i.test(pack)?'Kg':/litre|\\bL\\b/i.test(pack)?'Litre':'Adet',stock_status:'Fiyat / stok için teklif alın',legacy:true}};const merge=(managed,legacy)=>{const seen=new Set(),out=[];for(const p of managed){const k=String(p.source_product_id||p.id||p.name).toLocaleLowerCase('tr-TR');if(!seen.has(k)){seen.add(k);out.push(p)}}for(const raw of legacy){const p=normalizeLegacy(raw),k=String(p.source_product_id||p.id||p.name).toLocaleLowerCase('tr-TR');if(!seen.has(k)){seen.add(k);out.push(p)}}return out.slice(0,500)};const params=new URLSearchParams(location.search),initialQ=params.get('q')||'',initialCategory=params.get('category')||'',filter=params.get('filter')||'';cq.value=initialQ;let all=[];function visual(p){return '<div class=\\\"visualFallback\\\"><b>'+emoji(p)+'</b><span>'+esc(p.name||'Ürün')+'</span></div>'}function card(p){const id=String(p.source_product_id||p.id||''),name=String(p.name||'Ürün'),cat=String(p.category||''),unit=String(p.unit||'Adet'),pack=String(p.package||p.pack||p.package_text||''),price=p.effectivePrice??p.price??null;return '<article class=\\\"product\\\"><a class=\\\"img\\\" href=\\\"/urun/'+encodeURIComponent(slug(name))+'\\\">'+(p.image?'<img src=\\\"'+esc(p.image)+'\\\" alt=\\\"'+esc(name)+'\\\">':visual(p))+'</a><div class=\\\"badges\\\">'+(p.legacy?'<span class=\\\"badge legacyBadge\\\">ESKİ KATALOG</span>':'')+'</div><h3>'+esc(name)+'</h3><div class=\\\"meta\\\">'+esc(p.brand||cat)+'<br>'+esc(pack||cat)+'</div><div class=\\\"price\\\"><strong>'+money(price)+'</strong></div><div class=\\\"stock\\\">'+esc(p.stock_status||p.stock||p.stockStatus||'Siparişe uygun')+'</div><div class=\\\"qty\\\"><button data-minus>-</button><input type=number min=1 value=1><button data-plus>+</button></div><button class=\\\"add\\\" data-add=\\\"'+esc(id)+'\\\" data-name=\\\"'+esc(name)+'\\\" data-unit=\\\"'+esc(unit)+'\\\">Sepete Ekle</button></article>'}function render(){const q=cq.value.toLocaleLowerCase('tr-TR'),c=cc.value;let list=all.filter(p=>(!q||(String(p.name||'')+' '+String(p.category||'')+' '+String(p.brand||'')).toLocaleLowerCase('tr-TR').includes(q))&&(!c||slug(p.category||'')===c||String(p.category||'')===c));if(filter==='discount')list=list.filter(p=>Number(p.discountPercent||0)>0||Number(p.listPrice||0)>Number(p.effectivePrice??p.price??Infinity));if(filter==='new')list=list.slice().reverse();catalogCount.textContent=list.length+' ürün';catalogGrid.innerHTML=list.map(card).join('')||'<div class=\\\"commerceBox\\\"><b>Ürün bulunamadı.</b><p><a href=\\\"/iletisim\\\">Bu ürünü Okyanus\\'tan iste →</a></p></div>'}Promise.all([fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]})),fetch('/api/products',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]}))]).then(([j,l])=>{all=merge(Array.isArray(j.products)?j.products:[],Array.isArray(l.products)?l.products:[]);const names=[...new Set(all.map(x=>x.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr'));cc.innerHTML='<option value=\\\"\\\">Tüm kategoriler</option>'+names.map(x=>'<option value=\\\"'+esc(slug(x))+'\\\">'+esc(x)+'</option>').join('');cc.value=initialCategory;render()}).catch(()=>catalogGrid.innerHTML='<div class=\\\"commerceBox\\\">Katalog yüklenemedi.</div>');cq.oninput=render;cc.onchange=render;document.addEventListener('click',e=>{const c=e.target.closest('.product');if(!c)return;const q=c.querySelector('input');if(e.target.matches('[data-plus]'))q.value=Math.max(1,Number(q.value||1)+1);if(e.target.matches('[data-minus]'))q.value=Math.max(1,Number(q.value||1)-1);if(e.target.matches('[data-add]')){const b=e.target,a=read(),id=b.dataset.add;if(!id){b.textContent='Ürün kodu eksik';return}const x=a.find(v=>v.id===id),qty=Math.max(1,Number(q.value||1)),p=all.find(v=>String(v.source_product_id||v.id||'')===id),price=p?(p.effectivePrice??p.price??null):null;if(x){x.qty+=qty;if(price!=null)x.price=price}else a.push({id,name:b.dataset.name,unit:b.dataset.unit||'Adet',qty,price});write(a);b.textContent='Sepete Eklendi ✓';setTimeout(()=>b.textContent='Sepete Ekle',1200)}})})();";
 return html(commerceClientShell('Ürünler | Okyanus EDT',body,script));
}
function commerceCartPage(){
 const body='<main class="wrap"><section class="page"><h1>Sepet / Teklif Listem</h1><p>Ürün ve miktarları kontrol edin, sonra teklif talebini gönderin.</p><div id="cr"></div><div id="cartSummary" class="commerceBox" style="margin:12px 0"></div><form id="qf" class="form"><input name="name" required placeholder="Ad Soyad"><input name="business" required placeholder="İşletme / Firma"><input name="phone" required placeholder="Telefon"><input name="email" type="email" required placeholder="E-posta"><textarea name="note" placeholder="Teklif notunuz"></textarea><label><input name="consent" type="checkbox" required style="width:auto"> KVKK bilgilendirmesini okudum.</label><button>Teklif Talebini Gönder</button><div id="qr" role="status"></div></form></section></main>';
 const script="(function(){const K='oky-commerce-cart-v2',read=()=>{try{const a=JSON.parse(localStorage.getItem(K)||'[]');return Array.isArray(a)?a.filter(x=>x&&x.id&&x.name):[]}catch{return[]}},write=a=>localStorage.setItem(K,JSON.stringify(a)),money=v=>{const n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(n):'Teklif fiyatı'};function draw(){const a=read();cr.innerHTML=a.length?a.map((x,i)=>{const line=Number.isFinite(Number(x.price))?money(Number(x.price)*Math.max(1,Number(x.qty||1))):'Teklif fiyatı';return '<div class=\\\"commerceCartRow\\\"><div><b>'+String(x.name).replace(/[&<>]/g,'')+'</b><br><small>'+line+'</small></div><input data-q=\\\"'+i+'\\\" type=number min=1 value=\\\"'+Math.max(1,Number(x.qty||1))+'\\\"><span class=u>'+String(x.unit||'Adet').replace(/[&<>]/g,'')+'</span><button data-rm=\\\"'+i+'\\\" type=button aria-label=\\\"Ürünü kaldır\\\">×</button></div>'}).join(''):'<div class=\\\"commerceBox\\\">Sepetiniz boş. <a href=\\\"/urunler\\\">Ürünlere git →</a></div>';const priced=a.filter(x=>Number.isFinite(Number(x.price)));const total=priced.reduce((t,x)=>t+Number(x.price)*Math.max(1,Number(x.qty||1)),0);cartSummary.innerHTML=a.length?'<b>Sepet özeti</b><p>'+a.length+' kalem • '+(priced.length===a.length?money(total):'Nihai fiyat teklif aşamasında netleşir')+'</p>':'<b>Sepet özeti</b><p>Henüz ürün eklenmedi.</p>'}cr.oninput=e=>{if(e.target.dataset.q!=null){const a=read(),i=Number(e.target.dataset.q);if(!a[i])return;a[i].qty=Math.max(1,Number(e.target.value||1));write(a);draw()}};cr.onclick=e=>{if(e.target.dataset.rm!=null){const a=read();a.splice(Number(e.target.dataset.rm),1);write(a);draw()}};qf.onsubmit=async e=>{e.preventDefault();const a=read();if(!a.length){qr.textContent='Önce ürün ekleyin.';return}const f=Object.fromEntries(new FormData(qf));const payload={customer:{name:f.name,business:f.business,phone:f.phone,email:f.email},products:a.map(x=>({id:x.id,name:x.name,quantity:Number(x.qty),unit:x.unit||'Adet'})),note:f.note||'',consent:{kvkk:true,textVersion:'2026-09-29-commerce-v2'}};qr.textContent='Gönderiliyor...';try{const r=await fetch('/api/quote',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),j=await r.json();qr.textContent=r.ok?'Teklif talebiniz alındı: '+(j.quoteNo||''):(j.message||j.error||'Teklif gönderilemedi.');if(r.ok){write([]);draw();qf.reset()}}catch(err){qr.textContent='Bağlantı hatası.'}};draw()})();";
 return html(commerceClientShell('Sepet / Teklif | Okyanus EDT',body,script));
}
function commerceProductPage(slug){
 const body='<main class="wrap"><section class="page" id="pd"><h1>Ürün yükleniyor…</h1></section><section class="section"><h2>Benzer Ürünler</h2><div id="rel" class="commerceGrid"></div></section></main>';
 const script="(function(){const target="+JSON.stringify(slug)+",K='oky-commerce-cart-v2';const slug=v=>String(v||'').toLocaleLowerCase('tr-TR').normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');const esc=v=>String(v??'').replace(/[&<>]/g,'');const money=v=>{const n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(n):'Fiyat için teklif alın'};fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).then(j=>{const a=j.products||[],p=a.find(x=>slug(x.name)===target||String(x.id)===target);if(!p){pd.innerHTML='<h1>Ürün bulunamadı</h1><a href=\\\"/urunler\\\">Kataloğa dön</a>';return}const price=p.effectivePrice??p.price??null,img=p.image?'<img src=\\\"'+String(p.image).replace(/[\\\"'<>]/g,'')+'\\\" alt=\\\"'+esc(p.name)+'\\\">':'Ürün görseli',stock=esc(p.stock_status||p.stockStatus||'Siparişe uygun');document.title=esc(p.seo_title||p.name||'Ürün')+' | Okyanus EDT';var md=document.querySelector('meta[name=\"description\"]');if(!md){md=document.createElement('meta');md.name='description';document.head.appendChild(md)}md.content=esc(p.seo_description||p.description||p.category||'Okyanus EDT profesyonel ürün kataloğu');pd.innerHTML='<div class=\\\"detail\\\"><div class=\\\"img\\\">'+img+'</div><div><h1>'+esc(p.name)+'</h1><p>'+esc(p.brand||p.category||'')+'</p><p>'+esc(p.package||p.package_text||p.unit||'')+'</p>'+(p.description?'<p>'+esc(p.description)+'</p>':'')+'<div class=\\\"price\\\"><strong>'+money(price)+'</strong></div><div class=\\\"stock\\\">'+stock+'</div><div class=\\\"qty\\\" style=\\\"max-width:190px;margin:14px 0\\\"><button type=\\\"button\\\" id=\\\"pdMinus\\\">-</button><input id=\\\"pdQty\\\" type=\\\"number\\\" min=\\\"1\\\" value=\\\"1\\\"><button type=\\\"button\\\" id=\\\"pdPlus\\\">+</button></div><button class=\\\"btn\\\" style=\\\"background:#0768b2;color:#fff;border:0\\\" id=\\\"pdAdd\\\">Sepete / Teklife Ekle</button><p><a href=\\\"/iletisim\\\">Bu ürün hakkında satış ekibine sor →</a></p></div></div>';const q=document.getElementById('pdQty');document.getElementById('pdPlus').onclick=()=>q.value=Math.max(1,Number(q.value||1)+1);document.getElementById('pdMinus').onclick=()=>q.value=Math.max(1,Number(q.value||1)-1);document.getElementById('pdAdd').onclick=()=>{let cart=[];try{cart=JSON.parse(localStorage.getItem(K)||'[]')}catch{}const id=String(p.id||'');if(!id){document.getElementById('pdAdd').textContent='Ürün kodu eksik';return}const qty=Math.max(1,Number(q.value||1)),x=cart.find(v=>v.id===id),price=p.effectivePrice??p.price??null;if(x){x.qty+=qty;if(price!=null)x.price=price}else cart.push({id,name:p.name,unit:p.unit||'Adet',qty,price});localStorage.setItem(K,JSON.stringify(cart));document.getElementById('pdAdd').textContent='Sepete Eklendi ✓'};rel.innerHTML=a.filter(x=>x.id!==p.id&&x.category===p.category).slice(0,5).map(x=>'<div class=\\\"commerceBox\\\"><b>'+esc(x.name)+'</b><p>'+esc(x.category||'')+'</p><p>'+money(x.effectivePrice??x.price??null)+'</p><a href=\\\"/urun/'+slug(x.name)+'\\\">İncele →</a></div>').join('')}).catch(()=>pd.innerHTML='<h1>Ürün yüklenemedi.</h1>')})();";
 return html(commerceClientShell('Ürün | Okyanus EDT',body,script));
}
